reference_solution:
def smallestDivisor(nums, threshold):
    lo, hi = 1, max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if sum((x + mid - 1) // mid for x in nums) <= threshold:
            hi = mid
        else:
            lo = mid + 1
    return lo

brute_force_solution:
def smallestDivisor(nums, threshold):
    d = 1
    while sum((x + d - 1) // d for x in nums) > threshold:
        d += 1
    return d

